import { captureAuthUpdate } from './authUpdate';
import { z } from 'zod';
import { createLogger } from '../utils/logger';
import { getConfigManager } from './ConfigManager';
import { PROXY_URL } from '../config/proxy';
import { AuthorizationUnavailable } from '../storage/library/BrowserAuthorizationRecords';
import { errorMessage } from '../utils/errorMessage';

const log = createLogger('BrowserAgentClient');

export type EvidenceStatus = 'captured' | 'partial' | 'inferred';

export interface BrowserEvidence {
  finalUrl: string;
  rootVariables: Record<string, string>;
  elementStyles: Record<string, Record<string, string>>;
  fonts: string[];
  screenshotBase64?: string;
  evidenceStatus: EvidenceStatus;
  warnings: string[];
}

const BrowserEvidenceSchema: z.ZodType<BrowserEvidence> = z.object({
  finalUrl: z.string(),
  rootVariables: z.record(z.string(), z.string()),
  elementStyles: z.record(z.string(), z.record(z.string(), z.string())),
  fonts: z.array(z.string()),
  screenshotBase64: z.string().optional(),
  evidenceStatus: z.enum(['captured', 'partial', 'inferred']),
  warnings: z.array(z.string()),
});

export interface RenderViewport {
  width: number;
  height: number;
}

export type BrowserEvidenceResult =
  | { ok: true; evidence: BrowserEvidence }
  | { ok: false; available: boolean; reason: string };

export class BrowserAgentClient {
  private configManager = getConfigManager();

  constructor(private proxyUrl: string = PROXY_URL) {}

  async captureDesignEvidence(
    url: string,
    options: { viewport?: RenderViewport; screenshot?: boolean } = {},
  ): Promise<BrowserEvidenceResult> {
    const authToken = this.configManager.getAuthToken();
    if (!authToken) {
      return {
        ok: false,
        available: false,
        reason:
          'Not authenticated; run `rivet login` to enable browser evidence.',
      };
    }
    try {
      return await this.request(url, options, 0);
    } catch (error) {
      if (error instanceof AuthorizationUnavailable) {
        return { ok: false, available: false, reason: error.message };
      }
      throw error;
    }
  }

  private async request(
    url: string,
    options: { viewport?: RenderViewport; screenshot?: boolean },
    retryCount: number,
  ): Promise<BrowserEvidenceResult> {
    const authToken = this.configManager.getAuthToken();
    if (!authToken) {
      return { ok: false, available: false, reason: 'Not authenticated.' };
    }

    let response: Response;
    try {
      response = await fetch(`${this.proxyUrl}/api/browser-agent/render`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${authToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          url,
          ...(options.viewport ? { viewport: options.viewport } : {}),
          ...(options.screenshot ? { screenshot: true } : {}),
        }),
      });
    } catch (error) {
      return {
        ok: false,
        available: false,
        reason: `Could not reach browser agent: ${errorMessage(
          error,
          'network error',
        )}`,
      };
    }

    if (response.status === 401 && retryCount === 0) {
      log.warn('Token expired, attempting to refresh...');
      const refreshed = await this.refreshAccessToken();
      if (refreshed) {
        return this.request(url, options, retryCount + 1);
      }
      return {
        ok: false,
        available: false,
        reason: 'Authentication expired; run `rivet login` again.',
      };
    }

    if (response.status === 503) {
      return {
        ok: false,
        available: false,
        reason: 'Browser evidence capture is not enabled on the server.',
      };
    }

    if (!response.ok) {
      const body = await response.json().catch(() => ({}));
      const reason =
        (body as { error?: string }).error ??
        `Browser agent render failed (${response.status}).`;
      return { ok: false, available: true, reason };
    }

    const body = z
      .object({
        success: z.literal(true),
        evidence: BrowserEvidenceSchema,
      })
      .safeParse(await response.json().catch(() => ({})));
    if (!body.success) {
      return {
        ok: false,
        available: true,
        reason: 'Browser agent returned an unexpected response.',
      };
    }
    return { ok: true, evidence: body.data.evidence };
  }

  private async refreshAccessToken(): Promise<boolean> {
    const updateAuth = captureAuthUpdate(this.configManager);
    const refreshToken = this.configManager.getRefreshToken();
    if (!refreshToken) {
      log.warn('No refresh token available');
      return false;
    }
    try {
      const response = await fetch(`${this.proxyUrl}/api/auth/refresh`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ refreshToken }),
      });
      if (!response.ok) return false;
      const result = await response.json();
      if (result.success && result.token) {
        updateAuth(result);
        return true;
      }
      return false;
    } catch (err) {
      log.warn('Error refreshing token:', err);
      return false;
    }
  }
}
